    OPT_xpPreview_TIP = "Zeigt hinter dem Stand von Blizzards Erfahrungsleiste hell die Erfahrung deiner fertigen Quests und blass die aller Quests im Log. Maus über die Leiste: „nach Abgabe Stufe X, Y %“. Die Erfahrung je Quest nennt das Questlog; nennt es keine, bleibt die Leiste unverändert. Auf Höchststufe oder mit ausgeschalteter Erfahrung zeigt ezQuest nichts, ebenso wenn ein anderes Addon die Leiste ausblendet oder ersetzt.",
    -- Quests teilen (Share.lua; Wunsch des Nutzers vom 18.11.2026, ab Werk aus mit Hinweis)
    OPT_HEADER_SHARE = "Quests teilen",
    OPT_autoShare = "Angenommene Quests automatisch teilen",
    OPT_autoShare_TIP = "Ab Werk aus, weil ezQuest dabei ohne deinen Klick etwas an deine Mitspieler sendet. An: Nimmst du in einer Gruppe oder einem Schlachtzug eine Quest an, die sich teilen lässt, bietet ezQuest sie deinen Mitspielern über Blizzards Teilen an – wie der Knopf „Teilen“ im Questlog. Höchstens eine Quest alle 2 Sekunden, jede nur einmal, während eines Kampfs erst danach. Nicht allein, nicht für Quests, die dir ein Spieler geteilt hat, und nicht, wenn alle Mitspieler sie schon haben (soweit das Spiel es verrät). Wer sie angenommen hat, meldet Blizzard im Chat; die zuletzt geteilte Quest nennt „Status“ unter „Erweitert“.",
    OPTIN_LABEL_routeArrow = "Leveling-Route: Pfeil beim Weiterrücken",
    OPTIN_routeArrow = "Schaltet beim Weiterrücken der Leveling-Route ohne Klick Blizzards Zielverfolgung (Pfeil und Entfernung) auf den nächsten Schritt um – mit ezMaps „Zielverfolgung einschalten“, wie bei der Sammel-Route. Du hattest den alten Haken „Pfeil beim Weiterrücken“ aus; deshalb bleibt es aus, bis du hier einschaltest.",
    OPTIN_autoShare = "Bietet jede teilbare Quest, die du in einer Gruppe annimmst, ohne Klick deinen Mitspielern über Blizzards Teilen an – höchstens eine alle 2 Sekunden, nie im Kampf.",
    OPTIN_WHERE_autoShare = "Auch: das Zahnrad oben rechts im Questlog.",
    OPT_SHARE_NOW = "Teilbare Quests teilen",
    OPT_SHARE_NOW_BUTTON = "Jetzt teilen",
    SHARE_MENU_NOW = "Teilbare Quests jetzt teilen (%d)",
    SHARE_MENU_NOW_TIP = "Ein Klick: Bietet alle Quests in deinem Questlog, die sich teilen lassen, deinen Mitspielern über Blizzards Teilen an – eine alle 2 Sekunden, ohne die, die alle schon haben (soweit das Spiel es verrät). Nur in einer Gruppe; im Kampf geht es gleich danach weiter.",
    SHARE_SOLO = "Teilen geht nur in einer Gruppe oder einem Schlachtzug.",
    SHARE_NONE = "Keine Quest im Questlog lässt sich gerade teilen.",
    SHARE_QUEUED = "Teile %d |4Quest:Quests; mit der Gruppe – eine alle %d Sekunden.",
    STATUS_SHARE_LAST = "Zuletzt geteilt: %s (in dieser Sitzung: %d)",
    STATUS_SHARE_QUEUED = "Quests teilen: %d in der Reihe",
    STATUS_SHARE_COMBAT = "wartet auf das Ende des Kampfes",
