    XPP_ALL = "Alle Quests im Log (%d): %s EP%s",
    XPP_DONE_NONE = "Noch keine Quest fertig.",
    XPP_AFTER = " – nach Abgabe Stufe %d, %s",
    XPP_AFTER_MAX = " – nach Abgabe Höchststufe %d",
    XPP_GUESS = " (geschätzt)",
    XPP_GUESS_TIP = "Geschätzt: Der Client nennt die nötige Erfahrung nur für deine jetzige Stufe; jede weitere Stufe rechnet ezQuest mit derselben Zahl.",
    XPP_UNKNOWN_ONE = "%d Quest ohne Erfahrung im Questlog – nicht mitgezählt.",
    XPP_UNKNOWN_MANY = "%d Quests ohne Erfahrung im Questlog – nicht mitgezählt.",
    XPP_NONE = "Das Questlog nennt für keine deiner Quests Erfahrung – darum zeigt die Leiste keine Vorschau.",
    XPP_EMPTY = "Keine Quest im Log.",
