    XPP_STATUS_NONE = "Erfahrungsleiste: das Questlog nennt keine Erfahrung – keine Vorschau",
    XPP_STATUS_BLOCKED = "Erfahrungsleiste: du bekommst keine Erfahrung (Höchststufe oder ausgeschaltet) – keine Vorschau",
    XPP_STATUS_NOBAR = "Erfahrungsleiste: Blizzards Leiste nicht gefunden – keine Vorschau",
    XPP_STATUS_HIDDEN = "Erfahrungsleiste: Blizzards Leiste ist gerade nicht zu sehen (ausgeblendet, eine andere Leiste steht dort oder ein Addon ersetzt sie)",
    XPP_STATUS_EMPTY = "Erfahrungsleiste: keine Quest im Log – keine Vorschau",
    XPP_AFTER_CAP = " – nach Abgabe Stufe %d, die Grenze deines Kontos (weitere Erfahrung wird gesammelt)",
    -- Leveling-Route (LevelRoute.lua; Idee des Nutzers vom 16.11.2026, Antworten vom 17.11.2026)
    OPT_HEADER_ROUTE = "Leveling-Route",
    OPT_HEADER_ROUTE_TIP = "Eine Reihenfolge für die Quests in deinem Questlog: Ziele bündeln, abgeben, ohne Doppelwege – bewertet nach Erfahrung je Zeit. Zu finden im Zahnrad-Menü oben rechts am Questlog und im ezMap-Knopf der Weltkarte (Abschnitt „Reise“).",
    OPT_levelRoute = "Leveling-Route anbieten",
    OPT_levelRoute_TIP = "Zeigt im Zahnrad-Menü oben rechts am Questlog (und mit ezMap im Kartenknopf unter „Reise“) den Eintrag „Leveling-Route“. Gerechnet wird mit „Route automatisch berechnen“ von selbst, sonst, wenn du „Route berechnen“ klickst: aus den Quests deines Logs, ihren Zielen in deiner Zone und allen Abgaben. Erfahrung laut Questlog, Orte laut Spiel bzw. laut Questie, wenn es läuft (Schalter bzw. Klick gelten als Wunsch nach diesen Orten); gespeichert wird davon nichts. Aus: kein Eintrag, nichts wird gerechnet.",
    OPT_routeAuto = "Route automatisch berechnen",
    OPT_routeAuto_TIP = "Rechnet die Leveling-Route von selbst: kurz nach dem Einloggen und, solange noch keine Route besteht, sobald Quests in deinem Log stehen. Danach rückt die Route wie gewohnt weiter und fügt neue Quests ein; neu gerechnet wird nach einem Abbruch, einer geänderten Einstellung, wenn du in eine andere Zone kommst und wenn du die Weltkarte öffnest, nachdem du dich ein Stück bewegt hast – die Route beginnt dann an deinem jetzigen Ort. Während eines Kampfs erst danach und ohne Meldung im Chat – im Menü steht „Automatisch berechnet …“. Nicht von selbst für Charaktere ohne Erfahrung (Höchststufe, Erfahrung beim Lehrer ausgeschaltet). Markierung, Pfeil und Questverfolgung stellt sie dabei nicht um; das bleibt bei deinem Klick bzw. den Haken. „Route verwerfen“ bzw. „Abbrechen“ hält das automatische Rechnen an, bis du wieder „Route berechnen“ klickst. Aus: die erste Route kommt nur auf Klick; eine bestehende rechnet nach einem Abbruch oder einer geänderten Einstellung weiter von selbst neu (wie vorher).",
    OPT_routeVendor = "Händler am Weg einplanen",
    OPT_routeVendor_TIP = "Sind deine Taschen fast voll (höchstens so viele Plätze frei wie bei „Händler einplanen bei höchstens … freien Plätzen“) oder liegt ein Teil deiner Ausrüstung unter 25 % Haltbarkeit, plant die Leveling-Route einen bei dir gesehenen Händler bzw. Reparierer ein – vor dem nächsten Ziel und nur, wenn der Umweg höchstens „Grenze eines Abstechers“ beträgt; sonst steht ein Hinweis im Menü, ebenso, wenn noch kein Händler bekannt ist. Geprüft beim Berechnen und unterwegs, wenn sich deine Taschen oder die Haltbarkeit ändern; am Händler und mit wieder freien Taschen fällt der Halt weg. Was verkauft wird, entscheiden wie bisher ezMerchant und ezBag am Händler.",
    OPT_routeVendorFree = "Händler einplanen bei höchstens … freien Plätzen",
    OPT_routeVendorFree_TIP = "Hast du höchstens so viele freie Plätze in deinen normalen Taschen, plant die Leveling-Route einen Händler ein (Standard 4). Wirkt nur mit „Händler am Weg einplanen“.",
    OPT_routeGather = "Kräuter und Erze am Weg mitnehmen",
    OPT_routeGather_TIP = "Nur mit Kräuterkunde bzw. Bergbau: Die Leveling-Route macht kleine Abstecher zu deinen gemerkten Sammel-Stellen am Weg (wo du mindestens zweimal geerntet hast und dein Rang reicht), höchstens so weit wie „Grenze eines Abstechers“. Die Schritte tragen das Symbol des Berufs, im Menü und auf der Weltkarte. Eine gemerkte Stelle kann gerade leer sein – dann „Schritt überspringen“.",
    OPT_routeDetour = "Grenze eines Abstechers",
    OPT_routeDetour_TIP = "So viele Yards Umweg darf ein Händler- oder Sammel-Abstecher der Leveling-Route höchstens kosten (Standard 60, 0 = nur, was genau am Weg liegt). Liegt kein Händler so nah, steht nur ein Hinweis im Menü.",
    OPT_routeHard = "Schwere Quests einplanen",
    OPT_routeHard_TIP = "Elite- und Dungeon-Quests sowie Quests mehr als drei Stufen über dir plant die Leveling-Route wie jede andere ein. Aus – etwa beim Leveln allein –, stehen sie mit Grund unter „Nicht in der Route“.",
    OPT_routeLine = "Leveling-Route als Linie auf der Weltkarte",
    OPT_routeLine_TIP = "Zeichnet die Leveling-Route als durchgehende Linie von Gold nach Orange auf Blizzards Weltkarte, von deinem Ort über alle Schritte, mit Pfeilen in Laufrichtung; der Abschnitt zum nächsten Schritt ist kräftig, jeder weitere blasser. Ab Werk trägt nur der nächste Schritt seine Nummer mit dem Ziel daneben (alle Nummern mit ezMaps Schalter „Nummern an allen Schritten der Route“); Maus über Nummer oder Linie nennt Route, Schritt und Entfernung; der Anfang folgt dir bei offener Karte, erledigte Schritte verschwinden. Sammel-Abstecher stehen dort mit dem Symbol ihres Berufs. Braucht ezMap.",
    OPT_routeMiniArrow = "Pfeil zur Leveling-Route auf der Minikarte",
    OPT_routeMiniArrow_TIP = "Das bringt dir: Ein kleiner goldener Pfeil am Rand der Minikarte zeigt zum nächsten Schritt der Leveling-Route, auch wenn er weit weg ist. Liegt der Schritt in Sicht, rückt der Pfeil nach innen an seine Stelle; bist du dort, verschwindet er. Er nimmt keine Mausklicks an und lässt Blizzards Markierung und Pfeil unberührt. Braucht ezMap.",
    OPT_routeWatch = "Nächste Quest der Route in Blizzards Verfolgung",
    OPT_routeWatch_TIP = "Ab Werk aus. Mit diesem Haken stellt ezQuest Blizzards Questverfolgung ohne Klick um: Die Quest des nächsten Schritts der Leveling-Route kommt in die Verfolgung, wenn du sie dort noch nicht verfolgst, und wieder heraus, sobald die Route weiterrückt oder verworfen wird, nach /reload oder dem nächsten Einloggen ebenso (dafür merkt sich ezQuest je Charakter nur die Quest-IDs). Heraus kommt nur, was ezQuest selbst aufgenommen hat – was du selbst verfolgst, bleibt. Während eines Kampfs erst danach. Questies eigener Tracker bietet für Einträge anderer Addons keine öffentliche Schnittstelle.",
    OPT_ROUTE_NOW = "Leveling-Route berechnen",
    OPT_ROUTE_NOW_BUTTON = "Berechnen",
    OPT_ROUTE_NOW_TIP = "Rechnet die Leveling-Route aus deinem Questlog und schreibt die ersten Schritte in den Chat. Dasselbe im Zahnrad-Menü oben rechts in der Questliste der Weltkarte (Eintrag „Leveling-Route“); als Befehl: /ezquest route. Den Stand nennt auch /ezquest status.",
    ROUTE_MENU = "Leveling-Route",
    ROUTE_MENU_HAS = "Leveling-Route (%s)",
    ROUTE_MENU_TIP = "Reihenfolge für die Quests in deinem Questlog: Ziele in deiner Zone bündeln, abgeben, ohne Doppelwege – viel Erfahrung früh. Klick auf einen Schritt setzt Blizzards Kartenmarkierung (mit ezMap; den Pfeil dazu mit ezMaps Schalter „Zielverfolgung einschalten“ oder einem Klick auf die Markierung); nach einem erfüllten Ziel oder einer Abgabe rückt die Markierung von selbst weiter. Ab Werk aus, unten als Haken zuschaltbar: die nächste Quest in Blizzards Verfolgung aufnehmen – ohne Klick. Der Pfeil rückt nur mit ezMaps Schalter „Zielverfolgung einschalten“ mit.",
    ROUTE_BUILD = "Route berechnen",
    ROUTE_REBUILD = "Neu berechnen",
    ROUTE_BUILD_TIP = "Rechnet die Route aus den Quests deines Logs. Orte kommen aus dem Spiel und, wenn Questie läuft, laut Questie – nur für Quests, die du schon hast; Orte und Route werden nicht gespeichert (nach /reload neu berechnet – mit „Route automatisch berechnen“ von selbst).",
    ROUTE_LAST_AUTO = "Automatisch berechnet %s",
    ROUTE_LAST_CLICK = "Berechnet %s",
    ROUTE_LAST_MS = " (Rechenzeit %d ms)",
    ROUTE_LAST_TIP = "Wann die Route zuletzt ganz gerechnet wurde. „Automatisch“: ohne Klick – nach dem Einloggen bzw. sobald Quests im Log stehen (Haken „Route automatisch berechnen“) und, auch ohne diesen Haken, nach einem Abbruch oder einer geänderten Einstellung. Seitdem rückt sie nach erfüllten Zielen und Abgaben nur weiter und fügt neue Quests ein. Die Rechenzeit misst nur die Rechnung selbst.",
    ROUTE_AUTO_WAIT = "Noch keine Route – rechnet von selbst, sobald Quests im Log stehen",
    ROUTE_AUTO_WAIT_TIP = "Mit „Route automatisch berechnen“ rechnet ezQuest die Route kurz nach dem Einloggen und, solange keine besteht, sobald du eine Quest annimmst. Erst nach einem Kampf und nicht, solange das Spiel deinen Ort nicht kennt (Instanz, Ladebildschirm). Sofort geht es mit „Route berechnen“.",
    ROUTE_AUTO_NOXP = "Nicht von selbst – du bekommst gerade keine Erfahrung",
    ROUTE_AUTO_NOXP_TIP = "Auf Höchststufe bzw. mit beim Lehrer ausgeschalteter Erfahrung rechnet ezQuest die Leveling-Route nicht von selbst; sie ordnet nach Erfahrung je Weg. Auf Wunsch rechnet „Route berechnen“ sie trotzdem.",
    ROUTE_AUTO_EMPTY = "Keine Quest der Route in deiner Nähe – rechnet neu nach einem Zonenwechsel",
    ROUTE_AUTO_EMPTY_TIP = "Die Route ohne Klick fand keine Quest mit Ort in deiner Nähe (andere Zone oder die Orte standen noch nicht bereit). Sie rechnet neu, sobald du die Zone wechselst, nach einem Ladebildschirm und einmal kurz nach dem Einloggen; eine neue Quest wird gleich eingefügt.",
    ROUTE_STATUS_NOXP = "Leveling-Route: noch nicht berechnet – du bekommst gerade keine Erfahrung, darum nicht von selbst (auf Wunsch: Zahnrad oben rechts in der Questliste » Leveling-Route » Route berechnen, Knopf „Berechnen“ auf der Einstellungsseite oder %s).",
    ROUTE_AUTO_HELD = "Automatisch angehalten – „Route berechnen“ startet es wieder",
    ROUTE_AUTO_HELD_TIP = "Du hast die Route verworfen bzw. ihre Rechnung abgebrochen; bis zum nächsten Klick auf „Route berechnen“ (bzw. /reload) rechnet ezQuest sie nicht von selbst wieder.",
    ROUTE_RUNNING = "Wird berechnet … (Schritt %d)",
    ROUTE_RUNNING_TIP = "Viele Quests: die Route wird über mehrere Bilder gerechnet. Das Ergebnis steht danach im Chat und hier.",
    ROUTE_CANCEL_TIP = "Bricht die laufende Rechnung ab. War es eine Rechnung ohne Klick, rechnet ezQuest danach nicht von selbst wieder, bis du „Route berechnen“ klickst.",
    ROUTE_STARTED = "Leveling-Route wird berechnet …",
