    ROUTE_STATUS_NONE = "Leveling-Route: noch nicht berechnet – Zahnrad oben rechts in der Questliste » Leveling-Route » Route berechnen, Knopf „Berechnen“ auf der Einstellungsseite oder %s.",
    MENU_STATUS_READY = "Zahnrad-Menü am Questlog: Abschnitt „ezQuest“ angemeldet, seit dem Einloggen noch nicht geöffnet (das Zahnrad steht oben rechts in der Questliste der Weltkarte).",
