    ROUTE_MORE = "Weitere Schritte (%d)",
    ROUTE_MORE_TIP = "Die übrigen Schritte der Route in ihrer Reihenfolge.",
    ROUTE_MARK = "Nächstes Ziel markieren",
    ROUTE_MARK_TIP = "Setzt Blizzards Kartenmarkierung auf den nächsten Schritt (mit ezMap), den Pfeil dazu mit ezMaps Schalter „Zielverfolgung einschalten“ (ab Werk aus; sonst ein Klick auf die Markierung auf der Weltkarte). Ab dann rückt die Markierung nach einem erfüllten Ziel, einer Abgabe, einem Händlerbesuch oder einer Ernte von selbst weiter; den Pfeil nimmt sie dabei nur mit ezMaps Schalter „Zielverfolgung einschalten“ mit. Setzt du selbst eine Markierung, folgt die Route nicht mehr.",
    ROUTE_SKIP = "Schritt überspringen",
    ROUTE_SKIP_TIP = "Nimmt den nächsten Schritt aus der Route, etwa eine leere Sammel-Stelle. Bei einer Quest gehen alle ihre Schritte unter „Nicht in der Route“, bei einer gebündelten Abgabe jede Quest dort.",
    ROUTE_CLEAR = "Route verwerfen",
