    ROUTE_VENDOR_NONE_TIP = "Die Route plant nur Händler ein, deren Fenster du schon einmal geöffnet hast und die zu dir passen. Bisher kennt ezCollection keinen – öffne beim nächsten Händler sein Fenster, dann plant die Route ihn ein.",
    ROUTE_VENDOR_ELSEWHERE = "Taschen fast voll – kein bekannter Händler auf diesem Kontinent",
    ROUTE_VENDOR_ELSEWHERE_REPAIR = "Ausrüstung fast kaputt – kein bekannter Reparierer auf diesem Kontinent",
    ROUTE_VENDOR_ELSEWHERE_TIP = "ezCollection kennt passende Händler bisher nur auf anderen Kontinenten; die Route plant Halte nur auf deinem Kontinent ein. Öffne hier beim nächsten Händler sein Fenster, dann plant die Route ihn ein.",
    ROUTE_PAUSED = "Pausiert – die Markierung gehört gerade: %s",
    ROUTE_PAUSED_TIP = "Eine andere Route hält gerade Blizzards Kartenmarkierung (etwa ezMaps Sammel-Route). Die Leveling-Route überschreibt sie nicht; „Nächstes Ziel markieren“ holt sie zurück.",
    ROUTE_NO_EZMAP = "Eine Markierung setzt ezMap, wenn es geladen ist.",
