    ROUTE_STATUS_WAIT = "Levelling route: not computed yet – computed by itself as soon as there are quests in your log and the game knows where you are (right away: gear at the top right of the quest list, Levelling route, Compute route; the button \"Compute\" on the settings page; or %s).",
    ROUTE_STATUS_NONE = "Levelling route: not computed yet – gear at the top right of the quest list, Levelling route, Compute route; the button \"Compute\" on the settings page; or %s.",
    MENU_STATUS_READY = "Gear menu of the quest log: section \"ezQuest\" registered, not opened since you logged in (the gear sits at the top right of the world map's quest list).",
    MENU_STATUS_SEEN = "Gear menu of the quest log: section \"ezQuest\" registered and already built.",
    MENU_STATUS_FAILED = "Gear menu of the quest log: the last build of the section \"ezQuest\" (or of its entry \"Levelling route\") raised an error (%d× since you logged in) – details in ezCore's error list. The route still works through the button on the settings page.",
    MENU_STATUS_MISSING = "Gear menu of the quest log: section \"ezQuest\" not registered (yet) – the client lacks Menu.ModifyMenu or registering failed; ezQuest tries again when you open the quest log. The route works through the button on the settings page or %s.",
    ROUTE_OFF = "The levelling route is switched off.",
