    ROUTE_TIP_REPAIR = "Repair: part of your equipment is below %s durability.",
    ROUTE_TIP_BAGS = "Sell: at most %d free slots in your bags.",
    ROUTE_TIP_GATHER = "Remembered spot, harvested %d× by you – may be empty right now. Detour about %d yards.",
    ROUTE_TIP_PLACE = "Place: %s %s, %s",
    ROUTE_SRC_CLIENT = "place according to the game",
    ROUTE_SRC_QUESTIE = "place according to Questie",
    ROUTE_SRC_OWN = "place seen by you",
    ROUTE_MORE = "More steps (%d)",
    ROUTE_MORE_TIP = "The remaining steps of the route in their order.",
    ROUTE_MARK = "Mark next objective",
    ROUTE_MARK_TIP = "Sets Blizzard's map pin on the next step (with ezMap), the arrow with ezMap's switch \"Turn on navigation\" (off by default; otherwise click the pin on the world map). From then on the pin moves on by itself after a completed objective, a turn-in, a vendor visit or a harvest; it takes the arrow along only with ezMap's switch \"Turn on navigation\". If you set a pin yourself, the route stops following.",
    ROUTE_SKIP = "Skip step",
    ROUTE_SKIP_TIP = "Removes the next step from the route, for example an empty gathering spot. For a quest, all its steps go to \"Not in the route\", for a bundled turn-in every quest of it.",
    ROUTE_CLEAR = "Discard route",
